-- Dry-run probe for 20261118000000_photo_receipt_export_note.sql (PR 757).
-- Runs after the migration batch inside the harness's forced-rollback
-- transaction. Plain assertions only: no role/profile changes, no helpers.
-- Raises (failing the run) on any mismatch.

do $$
declare
  v_count int;
  v_before text;
  v_after text;
  v_person uuid;
  v_role text;
begin
  perform pg_temp.dry_run_as_system();
  select count(*) into v_count
  from public.app_release_notes
  where id = '2026-10-06-photo-receipt-export';
  if v_count <> 1 then
    raise exception 'photo-receipt-export note: expected 1 row, found %', v_count;
  end if;

  perform 1 from public.app_release_notes
  where id = '2026-10-06-photo-receipt-export'
    and published_on = date '2026-10-06'
    and audience = array[0, 1, 2, 3]
    and kind = 'improvement'
    and title_en = 'Export photos and receipts'
    and title_es = 'Exportar fotos y recibos'
    and body_en like '%ZIP%' and body_en like '%original document%'
    and body_es like '%ZIP%' and body_es like '%documento original%'
    and href = '/photos';
  if not found then
    raise exception 'photo-receipt-export note: row content mismatch';
  end if;

  -- Reapply the same insert: must be a no-op leaving the original row intact.
  select row_to_json(n)::text into v_before
  from public.app_release_notes n where id = '2026-10-06-photo-receipt-export';

  insert into public.app_release_notes
    (id, published_on, audience, kind, title_en, title_es, body_en, body_es, href)
  values ('2026-10-06-photo-receipt-export', date '2026-10-07', array[0], 'fix',
          'changed', 'changed', 'changed', 'changed', null)
  on conflict (id) do nothing;

  select count(*) into v_count
  from public.app_release_notes where id = '2026-10-06-photo-receipt-export';
  select row_to_json(n)::text into v_after
  from public.app_release_notes n where id = '2026-10-06-photo-receipt-export';
  if v_count <> 1 or v_after is distinct from v_before then
    raise exception 'photo-receipt-export note: reapply changed or duplicated the row';
  end if;

  perform pg_temp.dry_run_check('export note exact content and one row', true);
  perform pg_temp.dry_run_check('export note reapply preserves original row', v_count = 1 and v_after is not distinct from v_before);
  foreach v_role in array array['installer','foreman','supervisor','owner'] loop
    perform pg_temp.dry_run_as_system();
    if v_role in ('installer','foreman') then
      v_person := pg_temp.dry_run_pick(v_role);
    else
      -- Existing production aliases carry the same ranks as the canonical UI
      -- names. Read an active real account; never modify a profile to test it.
      select p.id into v_person from public.profiles p
       where p.role in (v_role, case when v_role = 'supervisor' then 'admin' else 'big_boss' end)
        and not coalesce(p.is_test, false) and not coalesce(p.is_partner, false)
        and p.retired_at is null and p.access_revoked_at is null
       order by p.id limit 1;
      if v_person is null then raise exception 'dry run: no active real account for % or its legacy alias', v_role; end if;
    end if;
    perform pg_temp.dry_run_act_as(v_person);
    select count(*) into v_count from public.app_release_notes where id = '2026-10-06-photo-receipt-export';
    perform pg_temp.dry_run_check(v_role || ' sees export note', v_count = 1, format('%s rows', v_count));
  end loop;
  perform pg_temp.dry_run_as_system();
  select count(*) into v_count from supabase_migrations.schema_migrations where version <> all(array['20260715000000','20260715000100','20260715120000','20260715200000','20260715210000','20260715230000','20260715240000','20260716000000','20260716001000','20260716002000','20260716003000','20260716004000','20260716005000','20260716010000','20260717000000','20260717001000','20260717002000','20260717003000','20260717004000','20260717005000','20260717006000','20260717007000','20260717008000','20260717009000','20260717140000','20260718000000','20260718001000','20260718002000','20260718003000','20260718004000','20260718005000','20260718006000','20260718007000','20260718010000','20260718023000','20260718030000','20260718040000','20260718040030','20260718050000','20260718050030','20260718060000','20260718060030','20260718070000','20260718080000','20260718080030','20260718090000','20260720000000','20260720010000','20260720020000','20260721000000','20260721002000','20260721010000','20260721020000','20260721030000','20260723010000','20260723020000','20260723030000','20260723040000','20260723040030','20260723050000','20260723060000','20260723060030','20260724000000','20260727000000','20260728000000','20260728130000','20260728140000','20260728150000','20260728160000','20260728170000','20260729200000','20260729200100','20260729210000','20260729210100','20260729210200','20260729220000','20260729230000','20260729240000','20260730000000','20260730010000','20260730120000','20260730130000','20260730160000','20260730180000','20260730210000','20260730220000','20260730230000','20260731000000','20260731010000','20260810000000','20260811000000','20260811010000','20260811020000','20260811030000','20260811040000','20260811050000','20260811060000','20260811070000','20260811080000','20260811090000','20260812000000','20260813000000','20260813010000','20260814000000','20260815000000','20260816000000','20260817000000','20260818000000','20260819000000','20260820000000','20260821000000','20260822000